import com.mongodb.client.*;
import org.bson.Document;
import java.util.Arrays;

public class MongoAggregationDemo {
    public static void main(String[] args) {
        try (MongoClient mongoClient = MongoClients.create("mongodb://localhost:27017")) {
            MongoDatabase database = mongoClient.getDatabase("ecommerce");
            MongoCollection<Document> collection = database.getCollection("orders");

            // Creating an index to support the aggregation pipeline match stage
            collection.createIndex(new Document("status", 1).append("orderDate", 1));

            // Executing an aggregation pipeline
            AggregateIterable<Document> result = collection.aggregate(Arrays.asList(
                new Document("$match", new Document("status", "COMPLETED")),
                new Document("$group", new Document("_id", "$customerId")
                    .append("totalSpent", new Document("$sum", "$orderTotal"))),
                new Document("$sort", new Document("totalSpent", -1)),
                new Document("$limit", 5)
            ));

            for (Document doc : result) {
                System.out.println(doc.toJson());
            }
        }
    }
}
